<script lang="ts">
  import {projectHref} from "../../workspace/project.ts";
  import {workspaceURL as projectSourceURL} from "../../workspace/location.svelte.ts";
  import {onMount,tick,untrack} from 'svelte';
  import type {WorkspaceTimeline,WorkspaceTimelineGroup} from '../../../../../src/services/workspace-timeline-contract.ts';
  import {flattenTimeline,indexAt,reconcileTimelineAnchor,viewportItems,barPosition,unitLabel,timelineCollapseSession,type Density,type TimelineItem} from './model.ts';
  import TimelineRuler from './TimelineRuler.svelte';
  import TimelineGroupRow from './TimelineGroupRow.svelte';
  let {timeline,density='compact',projectKey,onInspect,onSpecInspect,traceHref,onLogicalIds,onNavigate}:{timeline:WorkspaceTimeline;density?:Density;projectKey:string;onInspect:(event:MouseEvent,id:string)=>void;onSpecInspect:(event:MouseEvent,id:string)=>void;traceHref:(id:string)=>string;onLogicalIds:(ids:string[])=>void;onNavigate:(event:MouseEvent)=>void}=$props();
  const collapsedByProject=timelineCollapseSession;
  let collapsed=$state(new Set<string>()),scrollTop=$state(0),height=$state(600),width=$state(1000),coarse=$state(false),focusedKey=$state<string|undefined>(),pane:HTMLDivElement;
  const flat=$derived(flattenTimeline(timeline.groups,collapsed,density,coarse));
  const virtual=$derived(flat.taskCount>500),items=$derived(viewportItems(flat.items,flat.taskCount,scrollTop,height,focusedKey));
  let previousItems:TimelineItem[]=[],previousProject='';
  // Each component lives for this route session. Project changes cannot inherit another workspace's collapse state.
  $effect(()=>{const key=projectKey,groups=timeline.groups;untrack(()=>{if(previousProject!==key){previousProject=key;collapsed=new Set(collapsedByProject.get(key)??[]);}const present=new Set(groups.map(group=>group.specId));const next=new Set([...collapsed].filter(id=>present.has(id)));if(next.size!==collapsed.size)collapsed=next;collapsedByProject.set(key,next);});});
  $effect(()=>{onLogicalIds(flat.logicalIds);});
  $effect(()=>{const next=flat.items;untrack(()=>{if(pane&&previousItems.length&&next!==previousItems){const restored=reconcileTimelineAnchor(previousItems,next,pane.scrollTop);if(restored!==undefined){pane.scrollTop=restored;scrollTop=pane.scrollTop;}if(focusedKey&&!next.some(item=>item.key===focusedKey)){const old=previousItems.find(item=>item.key===focusedKey);focusedKey=undefined;if(old){const group=next.find(item=>item.kind==='group'&&item.group.specId===old.group.specId)??next.find(item=>item.kind==='group');if(group){pane.scrollTop=group.top;scrollTop=pane.scrollTop;void tick().then(()=>pane.querySelector<HTMLButtonElement>(`[data-group-toggle="${CSS.escape(group.group.specId)}"]`)?.focus({preventScroll:true}));}else pane.focus({preventScroll:true});}}}previousItems=next;});});
  function toggle(group:WorkspaceTimelineGroup){const next=new Set(collapsed);if(next.has(group.specId))next.delete(group.specId);else next.add(group.specId);collapsed=next;collapsedByProject.set(projectKey,next);}
  function focusChanged(event:FocusEvent){const key=(event.target as Element)?.closest<HTMLElement>('[data-timeline-key]')?.dataset.timelineKey;focusedKey=key;}
  function left(event:FocusEvent){if(!(event.relatedTarget instanceof Node)||!pane.contains(event.relatedTarget))focusedKey=undefined;}
  export function scrollPosition(){return {top:pane?.scrollTop??0,left:pane?.scrollLeft??0};}
  export function restoreScroll(value:{top:number;left:number}){if(pane){pane.scrollTop=value.top;pane.scrollLeft=value.left;scrollTop=pane.scrollTop;}}
  export function currentId(){return flat.items.find(item=>item.key===focusedKey&&item.kind==='task')?.kind==='task'?(flat.items.find(item=>item.key===focusedKey) as Extract<TimelineItem,{kind:'task'}>).task.taskId:flat.logicalIds[0];}
  export async function focusGroup(specId:string){
    const item=flat.items.find(item=>item.kind==='group'&&item.group.specId===specId);
    if(!item)return false;
    if(item.top<pane.scrollTop||item.top+item.height>pane.scrollTop+pane.clientHeight-32){pane.scrollTop=Math.max(0,item.top);scrollTop=pane.scrollTop;}
    await tick();const node=pane.querySelector<HTMLAnchorElement>(`[data-group-id="${CSS.escape(specId)}"] a`);node?.focus({preventScroll:true});return !!node;
  }
  export async function focusTask(id:string|undefined){
    const item=flat.items.find(item=>item.kind==='task'&&item.task.taskId===id);
    if(!item){const group=timeline.groups.find(group=>group.rows.some(task=>task.taskId===id));if(group){const header=flat.items.find(item=>item.kind==='group'&&item.group.specId===group.specId);if(header){pane.scrollTop=header.top;scrollTop=pane.scrollTop;await tick();pane.querySelector<HTMLButtonElement>(`[data-group-toggle="${CSS.escape(group.specId)}"]`)?.focus({preventScroll:true});return true;}}return false;}
    if(item.top<pane.scrollTop||item.top+item.height>pane.scrollTop+pane.clientHeight-32){pane.scrollTop=Math.max(0,item.top-32);scrollTop=pane.scrollTop;}
    await tick();const node=pane.querySelector<HTMLAnchorElement>(`[data-task-id="${CSS.escape(id!)}"] .task-id`);node?.focus({preventScroll:true});return !!node;
  }
  onMount(()=>{const media=matchMedia('(pointer:coarse)'),update=()=>coarse=media.matches;update();media.addEventListener('change',update);const observer=new ResizeObserver(()=>{height=pane.clientHeight;width=pane.clientWidth;});observer.observe(pane);height=pane.clientHeight;width=pane.clientWidth;return ()=>{observer.disconnect();media.removeEventListener('change',update);};});
</script>
<!-- svelte-ignore a11y_no_noninteractive_tabindex (Focusable scroll region uses native Arrow/Page/HomeEnd scrolling.) -->
<div class="timeline-grid" bind:this={pane} role="region" aria-label="Relative timeline" tabindex="0" onscroll={()=>scrollTop=pane.scrollTop} onfocusin={focusChanged} onfocusout={left}>
  <div class="head"><div class="labels"><span>Task / title</span><span>Status</span><span>Units</span></div>{#if timeline.unitsState==='available'}<TimelineRuler total={timeline.totalUnits} width={Math.max(320,width-480)-12}/>{:else}<span class="unavailable">Relative placement unavailable</span>{/if}</div>
  <div class="timeline-body" role="list" aria-label={`${flat.taskCount} tasks in expanded groups; simple table provides paginated reading`} class:virtual style:height={virtual?`${flat.height}px`:undefined}>
    {#each items as item(item.key)}
      <div class="item" class:positioned={virtual} role="listitem" aria-posinset={item.position} aria-setsize={flat.items.length} data-timeline-key={item.key} data-task-id={item.kind==='task'?item.task.taskId:undefined} style:top={virtual?`${item.top}px`:undefined} style:height={`${item.height}px`}>
        {#if item.kind==='group'}<TimelineGroupRow group={item.group} collapsed={collapsed.has(item.group.specId)} onToggle={()=>toggle(item.group)} onInspect={onSpecInspect}/>
        {:else}
          {@const task=item.task}{@const bar=timeline.unitsState==='available'?barPosition(task,timeline.totalUnits):undefined}
          <div class={`task-row ${task.selectionState}`}>
            <div class="labels task-labels"><div class="title"><a class="task-id" href={projectHref(`/tasks/${task.taskId}`,projectSourceURL())} onclick={event=>onInspect(event,task.taskId)} data-sveltekit-preload-data="off" data-sveltekit-preload-code="off">{task.taskId}</a><a class="task-title" href={projectHref(`/tasks/${task.taskId}`,projectSourceURL())} title={task.title} onclick={event=>onInspect(event,task.taskId)} data-sveltekit-preload-data="off" data-sveltekit-preload-code="off"><span class="title-text">{task.title}</span></a>{#if task.isCrossSpecRelated}<span class="cross" title="Related across specs">↗<span class="sr-only">Cross-spec relation</span></span>{/if}</div><span class={`status ${task.effectiveStatus}`} title={`${task.statusLabel}${task.archivedAt?' · archived':''}`}>{task.effectiveStatus==='done'?'✓':task.effectiveStatus==='blocked'?'!':task.effectiveStatus==='review'?'◇':'·'} {task.statusLabel}</span><span class="effort">{unitLabel(task.effort)}u</span></div>
            <div class="bar-cell">{#if bar}<span aria-hidden="true" class={`bar ${task.effectiveStatus}`} style:left={`${bar.left}%`} style:width={`max(6px,${bar.width}%)`}></span><a class="bar-hit" href={traceHref(task.taskId)} onclick={onNavigate} aria-label={`Trace ${task.taskId}: ${unitLabel(task.start)} to ${unitLabel(task.end)}, ${task.statusLabel}`} title={`${task.taskId} · ${task.selectionState.replaceAll('_',' ')} · ${unitLabel(task.start)} → ${unitLabel(task.end)}`} style:left={`clamp(0px,${bar.left}%,calc(100% - var(--hit-size)))`} style:width={`max(var(--hit-size),${bar.width}%)`}><span class="sr-only">Trace {task.taskId}</span></a>{:else}<a class="trace-unavailable" href={traceHref(task.taskId)} onclick={onNavigate}>Trace · {unitLabel(task.start)} → {unitLabel(task.end)}</a>{/if}</div>
          </div>
        {/if}
      </div>
    {/each}
  </div>
  {#if virtual}<p class="window-status" aria-live="off">Expanded tasks {Math.max(1,flat.items[indexAt(flat.items,scrollTop)]?.taskPosition??0)}–{Math.min(flat.taskCount,(flat.items[indexAt(flat.items,scrollTop+height)]?.taskPosition??flat.taskCount)+1)} of {flat.taskCount} · {items.filter(item=>item.kind==='task').length} mounted. Simple table offers paginated reading.</p>{/if}
  {#if !timeline.groups.length}<p class="empty">No tasks match these filters and mode.</p>{/if}
</div>
<style>
  .timeline-grid{flex:1 1 auto;min-height:0;overflow:auto;border:1px solid var(--border-control);border-radius:.25rem;background:var(--surface);overscroll-behavior:contain;overflow-anchor:none}.head,.task-row{display:grid;grid-template-columns:480px minmax(320px,1fr);min-width:800px}.head{position:sticky;top:0;z-index:3;height:32px;background:var(--surface-raised);border-bottom:1px solid var(--border-control);color:var(--text-muted);font-size:.6875rem}.labels{display:grid;grid-template-columns:minmax(0,1fr) 108px 48px;gap:8px;align-items:center;border-right:1px solid var(--border-control);padding:0 .625rem}.head .labels{position:sticky;left:0;z-index:4;background:var(--surface-raised)}.timeline-body{position:relative;min-width:800px}.item{width:100%;min-width:800px}.positioned{position:absolute;left:0}.task-row{height:100%;border-bottom:1px solid var(--border-subtle);font-size:.75rem}.task-labels{position:sticky;left:0;z-index:1;background:var(--surface)}.title{display:flex;align-items:center;gap:.5rem;min-width:0;height:100%}.task-id{flex-shrink:0;color:var(--accent);font-size:.8125rem;font-variant-numeric:tabular-nums}.task-title{font-size:.8125rem;min-width:0;overflow:hidden;white-space:nowrap;text-overflow:ellipsis;color:var(--text)}.title a{display:flex;align-items:center;min-height:24px;text-decoration:none}.title-text{min-width:0;overflow:hidden;white-space:nowrap;text-overflow:ellipsis}.title a:hover{text-decoration:underline}.status{overflow:hidden;white-space:nowrap;text-overflow:ellipsis;font-size:.6875rem;color:var(--text-muted)}.status.blocked{color:var(--danger)}.status.review{color:var(--warning)}.status.in_progress,.status.done{color:var(--accent)}.effort{text-align:right;color:var(--text-muted);font-size:.6875rem;font-variant-numeric:tabular-nums}.cross{color:var(--info)}.bar-cell{position:relative;margin-right:12px;--hit-size:24px}.bar-hit{position:absolute;top:0;bottom:0;min-width:var(--hit-size);min-height:var(--hit-size);max-width:100%;border-radius:3px}.window-status{position:sticky;left:0;bottom:0;margin:0;padding:.25rem .5rem;background:var(--surface-raised);border-top:1px solid var(--border-subtle);font-size:.6875rem;color:var(--text-muted);z-index:2;width:100%;font-variant-numeric:tabular-nums}.bar{position:absolute;top:7px;bottom:7px;min-height:16px;border:1px solid var(--border-control);border-radius:3px;background:var(--text-muted)}.bar.in_progress,.bar.done{background:var(--accent);border-color:var(--accent)}.bar.blocked{background:var(--danger);border-color:var(--danger)}.bar.review{background:var(--warning);border-color:var(--warning)}.selected .task-labels{background:var(--selection-bg)}.dependency .task-labels,.dependency_transitive .task-labels{border-left:3px solid var(--info)}.dependent .task-labels,.dependent_transitive .task-labels{border-left:3px solid var(--warning)}.blocked_dependent .task-labels,.blocked_dependent_transitive .task-labels{border-left:3px solid var(--danger)}.selected .bar{outline:2px solid var(--text);outline-offset:2px}.unavailable,.trace-unavailable{display:flex;align-items:center;padding:0 .5rem;font-size:.6875rem;color:var(--text-muted)}.trace-unavailable{height:100%;color:var(--accent)}.empty{margin:1rem;color:var(--text-muted);font-size:.8125rem}.bar-hit:focus-visible{outline:2px solid var(--focus-ring);outline-offset:2px}@media(pointer:coarse){.bar-cell{--hit-size:44px}.title a{min-height:44px}.title .task-title{min-width:44px}}
</style>
